class trigger;

template <class T>
class my_allocator {
};

template <class T>
void construct(T*, const T&);

template <class T>
void destroy(T*, T*);

template <class InputIterator, class ForwardIterator>
ForwardIterator uninitialized_copy(InputIterator, InputIterator, ForwardIterator);

template <class BidirectionalIterator1, class BidirectionalIterator2>
BidirectionalIterator2 copy_backward(BidirectionalIterator1, BidirectionalIterator1,
                                     BidirectionalIterator2);

template <class T, class Alloc>
class vector {
public:
  typedef T* iterator;
  typedef unsigned int size_type;

  iterator begin() { return _M_start; }
  iterator end() { return _M_finish; }
  size_type size() const { return size_type(_M_finish - _M_start); }
  iterator _M_allocate(size_type);
  void _M_deallocate(iterator, size_type);
  void _M_insert_aux(iterator, const T&);

  iterator _M_start;
  iterator _M_finish;
  iterator _M_end_of_storage;
};

template <class T, class Alloc>
void vector<T, Alloc>::_M_insert_aux(iterator position, const T& x) {
  if (_M_finish != _M_end_of_storage) {
    construct(_M_finish, *(_M_finish - 1));
    ++_M_finish;
    T x_copy = x;
    copy_backward(position, _M_finish - 2, _M_finish - 1);
    *position = x_copy;
  }
  else {
    const size_type old_size = size();
    const size_type len = old_size != 0 ? 2 * old_size : 1;
    iterator new_start = _M_allocate(len);
    iterator new_finish = new_start;
    new_finish = uninitialized_copy(_M_start, position, new_start);
    construct(new_finish, x);
    ++new_finish;
    new_finish = uninitialized_copy(position, _M_finish, new_finish);
    destroy(begin(), end());
    _M_deallocate(_M_start, _M_end_of_storage - _M_start);
    _M_start = new_start;
    _M_finish = new_finish;
    _M_end_of_storage = new_start + len;
  }
}

template void vector<trigger*, my_allocator<trigger*> >::_M_insert_aux(
    trigger**, trigger* const&);
